// receipt-report.js — small run-log report tool (Node.js builtins only).
//
// Exports: reduceEvents(text) -> {jobs, duplicates}
// CLI:     node receipt-report.js LOGFILE

import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';

const VALID_TYPES = new Set(['started', 'succeeded', 'failed']);

function fail(message) {
  throw new Error(message);
}

function isNonemptyString(value) {
  return typeof value === 'string' && value.length > 0;
}

function isSafeIntegerAtLeast(value, minimum) {
  return (
    typeof value === 'number' &&
    Number.isSafeInteger(value) &&
    value >= minimum
  );
}

function validateEvent(value, lineNumber) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    fail(`line ${lineNumber}: event must be a JSON object`);
  }
  if (!isNonemptyString(value.id)) {
    fail(`line ${lineNumber}: "id" must be a nonempty string`);
  }
  if (!isNonemptyString(value.job)) {
    fail(`line ${lineNumber}: "job" must be a nonempty string`);
  }
  if (!isSafeIntegerAtLeast(value.attempt, 1)) {
    fail(`line ${lineNumber}: "attempt" must be a positive safe integer starting at 1`);
  }
  if (!isSafeIntegerAtLeast(value.seq, 0)) {
    fail(`line ${lineNumber}: "seq" must be a nonnegative safe integer`);
  }
  if (!VALID_TYPES.has(value.type)) {
    fail(`line ${lineNumber}: "type" must be "started", "succeeded", or "failed"`);
  }
  return value;
}

function sameRequiredFields(a, b) {
  return (
    a.id === b.id &&
    a.job === b.job &&
    a.attempt === b.attempt &&
    a.seq === b.seq &&
    a.type === b.type
  );
}

export function reduceEvents(text) {
  if (typeof text !== 'string') {
    if (text instanceof Uint8Array) {
      text = Buffer.from(text).toString('utf8');
    } else {
      fail('reduceEvents: input must be a UTF-8 JSONL string');
    }
  }

  const lines = text.replace(/\r\n/g, '\n').split('\n');
  const byId = new Map();
  let duplicates = 0;

  for (let index = 0; index < lines.length; index++) {
    const line = lines[index];
    if (line.trim() === '') continue; // ignore whitespace-only lines
    let value;
    try {
      value = JSON.parse(line);
    } catch (err) {
      fail(`line ${index + 1}: invalid JSON: ${err.message}`);
    }
    const event = validateEvent(value, index + 1);
    const previous = byId.get(event.id);
    if (previous === undefined) {
      byId.set(event.id, event);
    } else if (sameRequiredFields(previous, event)) {
      duplicates += 1; // every extra identical copy counts
    } else {
      fail(`duplicate id ${JSON.stringify(event.id)} with different required fields`);
    }
  }

  // Reduce. Maps (not plain objects) so ids/jobs like "__proto__" are ordinary keys.
  const jobs = new Map();
  for (const event of byId.values()) {
    let attempts = jobs.get(event.job);
    if (attempts === undefined) {
      attempts = new Map();
      jobs.set(event.job, attempts);
    }
    const where = `job ${JSON.stringify(event.job)} attempt ${event.attempt}`;
    const state = attempts.get(event.attempt) ?? { start: null, terminal: null };
    if (event.type === 'started') {
      if (state.start !== null) {
        fail(`repeated start for ${where}`);
      }
      state.start = event;
    } else {
      if (state.terminal !== null) {
        fail(`repeated or contradictory terminal for ${where}`);
      }
      state.terminal = event;
    }
    attempts.set(event.attempt, state);
  }

  const reportJobs = [];
  for (const [job, attempts] of jobs) {
    const reportAttempts = [];
    for (const [attempt, state] of attempts) {
      if (state.start === null) {
        fail(`orphan terminal for job ${JSON.stringify(job)} attempt ${attempt}`);
      }
      if (state.terminal !== null && state.terminal.seq <= state.start.seq) {
        fail(
          `terminal seq ${state.terminal.seq} must be greater than start seq ` +
            `${state.start.seq} for job ${JSON.stringify(job)} attempt ${attempt}`
        );
      }
      reportAttempts.push({
        attempt,
        status: state.terminal === null ? 'running' : state.terminal.type,
        startedSeq: state.start.seq,
        finishedSeq: state.terminal === null ? null : state.terminal.seq,
      });
    }
    reportAttempts.sort((a, b) => a.attempt - b.attempt);
    reportJobs.push({ job, attempts: reportAttempts });
  }
  // JavaScript string < / > order (UTF-16 code units, not locale collation).
  reportJobs.sort((a, b) => (a.job < b.job ? -1 : a.job > b.job ? 1 : 0));

  return { jobs: reportJobs, duplicates };
}

function isMainModule() {
  const entry = process.argv[1];
  if (typeof entry !== 'string' || entry === '') return false;
  try {
    return import.meta.url === pathToFileURL(resolve(entry)).href;
  } catch {
    return false;
  }
}

if (isMainModule()) {
  const args = process.argv.slice(2);
  try {
    if (args.length !== 1) {
      throw new Error('usage: node receipt-report.js LOGFILE');
    }
    const text = readFileSync(args[0], 'utf8');
    const report = reduceEvents(text);
    process.stdout.write(`${JSON.stringify(report)}\n`);
  } catch (err) {
    const message = err instanceof Error ? err.message : String(err);
    process.stderr.write(`receipt-report: ${message}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { spawnSync } from 'node:child_process';
import { mkdtempSync, writeFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { reduceEvents } from '../receipt-report.js';

const jsonl = (events) => events.map((event) => JSON.stringify(event)).join('\n');
const start = (id, job, attempt, seq) => ({ id, job, attempt, seq, type: 'started' });
const end = (id, job, attempt, seq, type) => ({ id, job, attempt, seq, type });

test('empty and whitespace-only input', () => {
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
  assert.deepEqual(reduceEvents('  \t\r\n \n'), { jobs: [], duplicates: 0 });
});

test('CRLF endings and missing final newline', () => {
  const text =
    jsonl([start('s', 'j', 1, 0), end('t', 'j', 1, 1, 'succeeded')])
      .split('\n')
      .join('\r\n'); // CRLF, no trailing newline
  assert.deepEqual(reduceEvents(text), {
    jobs: [{ job: 'j', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 1 }] }],
    duplicates: 0,
  });
});

test('duplicates: every extra identical copy counted, extra fields ignored', () => {
  const event = start('s', 'x', 1, 0);
  const text = jsonl([event, { ...event }, { ...event, extra: 'a', other: 1 }, { ...event, extra: 'zzz' }]);
  assert.deepEqual(reduceEvents(text), {
    jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null }] }],
    duplicates: 3,
  });
});

test('repeated id with any different required field is an error', () => {
  const base = start('s', 'x', 1, 0);
  assert.throws(() => reduceEvents(jsonl([base, { ...base, seq: 1 }])), /different required fields/);
  assert.throws(() => reduceEvents(jsonl([base, { ...base, job: 'y' }])), Error);
  assert.throws(() => reduceEvents(jsonl([base, { ...base, attempt: 2 }])), Error);
  assert.throws(() => reduceEvents(jsonl([base, { ...base, type: 'failed' }])), Error);
  assert.throws(() => reduceEvents(jsonl([base, { ...base, id: 's ' }])), Error);
});

test('invalid JSON and malformed required fields are errors', () => {
  assert.throws(() => reduceEvents('{bad'), Error);
  assert.throws(() => reduceEvents('[1,2]'), Error);
  assert.throws(() => reduceEvents('null'), Error);
  assert.throws(() => reduceEvents('"string"'), Error);
  assert.throws(() => reduceEvents('{"id":"a","job":"b","attempt":1,"seq":0}'), Error); // missing type
  assert.throws(() => reduceEvents(jsonl([{ id: '', job: 'b', attempt: 1, seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 1, attempt: 1, seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: '1', seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1.5, seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 0, seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 2 ** 53, seq: 0, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1, seq: -1, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1, seq: '0', type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1, seq: Infinity, type: 'started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1, seq: 0, type: 'Started' }])), Error);
  assert.throws(() => reduceEvents(jsonl([{ id: 'a', job: 'b', attempt: 1, seq: 0, type: null }])), Error);
  assert.throws(() => reduceEvents('{"id":"a"} trailing'), Error);
});

test('orphan terminal, repeated starts, repeated/contradictory terminals are errors', () => {
  assert.throws(() => reduceEvents(jsonl([end('t', 'x', 1, 3, 'failed')])), /orphan/);
  assert.throws(
    () => reduceEvents(jsonl([start('s1', 'x', 1, 0), start('s2', 'x', 1, 1)])),
    /repeated start/
  );
  assert.throws(
    () => reduceEvents(jsonl([start('s', 'x', 1, 0), end('t1', 'x', 1, 5, 'succeeded'), end('t2', 'x', 1, 6, 'succeeded')])),
    /terminal/
  );
  assert.throws(
    () => reduceEvents(jsonl([start('s', 'x', 1, 0), end('t1', 'x', 1, 5, 'succeeded'), end('t2', 'x', 1, 6, 'failed')])),
    /terminal/
  );
  // later start rescues earlier terminal ordering (no orphan)
  assert.deepEqual(
    reduceEvents(jsonl([end('t', 'x', 1, 5, 'succeeded'), start('s', 'x', 1, 4)])),
    { jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 4, finishedSeq: 5 }] }], duplicates: 0 }
  );
});

test('terminal seq must be strictly greater than start seq', () => {
  assert.throws(() => reduceEvents(jsonl([start('s', 'x', 1, 5), end('t', 'x', 1, 5, 'failed')])), Error);
  assert.throws(() => reduceEvents(jsonl([start('s', 'x', 1, 5), end('t', 'x', 1, 4, 'failed')])), Error);
});

test('jobs sorted by code unit order, attempts numerically, attempts independent', () => {
  const text = jsonl([
    start('s10', 'Z', 10, 1),
    start('s2', 'Z', 2, 7),
    end('t2', 'Z', 2, 8, 'failed'),
    start('s1', 'a b', 1, 3),
    start('s-u', 'é', 1, 9), // 'é' (U+00E9) sorts after 'Z' by code units
  ]);
  assert.deepEqual(reduceEvents(text), {
    jobs: [
      { job: 'Z', attempts: [
        { attempt: 2, status: 'failed', startedSeq: 7, finishedSeq: 8 },
        { attempt: 10, status: 'running', startedSeq: 1, finishedSeq: null },
      ] },
      { job: 'a b', attempts: [{ attempt: 1, status: 'running', startedSeq: 3, finishedSeq: null }] },
      { job: 'é', attempts: [{ attempt: 1, status: 'running', startedSeq: 9, finishedSeq: null }] },
    ],
    duplicates: 0,
  });
});

test('ids and jobs like __proto__, whitespace, unicode are ordinary strings', () => {
  const text = jsonl([
    start('__proto__', 'x', 1, 0),
    end('constructor', 'x', 1, 2, 'succeeded'),
    start('hasOwnProperty', 'hasOwnProperty', 1, 0),
  ]);
  const report = reduceEvents(text);
  assert.equal(report.jobs.length, 2);
  assert.equal(report.jobs[0].job, 'hasOwnProperty');
  assert.equal(report.jobs[1].job, 'x');
  assert.equal(report.jobs[1].attempts[0].status, 'succeeded');
  // prototype chain untouched
  assert.equal(report.jobs[0].attempts[0].attempt, 1);
  assert.ok(Object.getPrototypeOf(report) === Object.prototype);
});

test('overlapping sequence ranges across attempts and shared seqs are fine', () => {
  const text = jsonl([
    start('s1', 'x', 1, 5), end('t1', 'x', 1, 9, 'succeeded'),
    start('s2', 'x', 2, 5), end('t2', 'x', 2, 9, 'failed'), // identical ranges, different attempts
    start('s3', 'y', 1, 7), end('t3', 'y', 1, 9, 'succeeded'), // shares seqs with job x
  ]);
  assert.deepEqual(reduceEvents(text).jobs, [
    { job: 'x', attempts: [
      { attempt: 1, status: 'succeeded', startedSeq: 5, finishedSeq: 9 },
      { attempt: 2, status: 'failed', startedSeq: 5, finishedSeq: 9 },
    ] },
    { job: 'y', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 7, finishedSeq: 9 }] },
  ]);
});

test('attempt gaps allowed; seq 0 allowed', () => {
  const text = jsonl([start('s', 'x', 1, 0), start('s2', 'x', 42, 1)]);
  assert.deepEqual(reduceEvents(text).jobs, [
    { job: 'x', attempts: [
      { attempt: 1, status: 'running', startedSeq: 0, finishedSeq: null },
      { attempt: 42, status: 'running', startedSeq: 1, finishedSeq: null },
    ] },
  ]);
});

// ---- CLI contract ----

const here = dirname(fileURLToPath(import.meta.url));
const scriptPath = join(here, '..', 'receipt-report.js');
let tmp;

test('CLI behavior', { before() { tmp = mkdtempSync(join(tmpdir(), 'receipt-')); }, after() { rmSync(tmp, { recursive: true, force: true }); } }, () => {
  const run = (args) => spawnSync(process.execPath, [scriptPath, ...args], { encoding: 'utf8' });
  const file = join(tmp, 'log.jsonl');
  writeFileSync(file, jsonl([start('s', 'x', 1, 0), end('t', 'x', 1, 3, 'succeeded')]) + '\n');
  const expected = { jobs: [{ job: 'x', attempts: [{ attempt: 1, status: 'succeeded', startedSeq: 0, finishedSeq: 3 }] }], duplicates: 0 };

  const ok = run([file]);
  assert.equal(ok.status, 0);
  assert.equal(ok.stdout, `${JSON.stringify(expected)}\n`);
  assert.equal(ok.stderr, '');

  const noArgs = run([]);
  assert.equal(noArgs.status, 2);
  assert.equal(noArgs.stdout, '');
  assert.ok(noArgs.stderr.length > 0);

  const tooMany = run([file, file]);
  assert.equal(tooMany.status, 2);
  assert.equal(tooMany.stdout, '');
  assert.ok(tooMany.stderr.length > 0);

  const missing = run([join(tmp, 'nope.jsonl')]);
  assert.equal(missing.status, 2);
  assert.equal(missing.stdout, '');
  assert.ok(missing.stderr.length > 0);

  const dir = run([tmp]); // a directory is unreadable as a file
  assert.equal(dir.status, 2);
  assert.equal(dir.stdout, '');
  assert.ok(dir.stderr.length > 0);

  const badLog = join(tmp, 'bad.jsonl');
  writeFileSync(badLog, '{"id":');
  const bad = run([badLog]);
  assert.equal(bad.status, 2);
  assert.equal(bad.stdout, '');
  assert.ok(bad.stderr.length > 0);
});

test('importing the module does not run the CLI', async () => {
  const mod = await import(pathToFileURL(scriptPath).href);
  assert.equal(typeof mod.reduceEvents, 'function');
  assert.deepEqual(reduceEvents(''), { jobs: [], duplicates: 0 });
});

