  console.log("2^53 rejected:", threw);
  // attempt: true rejected
  threw = false; try { reduceEvents("{\"id\":\"a\",\"job\":\"x\",\"attempt\":true,\"seq\":0,\"type\":\"started\"}"); } catch { threw = true; }
  console.log("bool attempt rejected:", threw);
  // lone CR between objects is not a line separator -> invalid JSON line
  threw = false; try { reduceEvents("{\"id\":\"a\",\"job\":\"x\",\"attempt\":1,\"seq\":0,\"type\":\"started\"}\\r{\"id\":\"b\",\"job\":\"x\",\"attempt\":1,\"seq\":1,\"type\":\"succeeded\"}"); } catch { threw = true; }
  console.log("lone CR rejected:", threw);
  // non-string input rejected
  threw = false; try { reduceEvents(42); } catch (e) { threw = e instanceof Error; }
  console.log("non-string rejected:", threw);
  // Buffer input accepted
  const buf = reduceEvents(Buffer.from("{\"id\":\"a\",\"job\":\"x\",\"attempt\":1,\"seq\":0,\"type\":\"started\"}"));
  console.log("buffer ok:", buf.jobs.length === 1);
  // duplicate with different extra fields only -> duplicate, not error
