  console.log("extra-field dup:", d.duplicates === 1);
  // __proto__ id via reduce + JSON output
  const p = reduceEvents("{\"id\":\"__proto__\",\"job\":\"x\",\"attempt\":1,\"seq\":0,\"type\":\"started\"}");
  console.log("proto id ok:", p.jobs[0].job === "x");
});
